build.xml  <!--   All content on this website (including text, images, source code and any other original works), unless otherwise noted, is licensed under a Creative Commons License.  http://creativecommons.org/licenses/by-nc-sa/2.5/  Copyright (C) 2004-2007 Open-Xchange, Inc. Mail: info@open-xchange.com  @author Viktor Pracht <viktor.pracht@open-xchange.com> @author Stefan Preuss <stefan.preuss@open-xchange.org>   -->  <project name="Open-Xchange AJAX-GUI" default="all" basedir=".">  <property name="htdoc" value="/var/www" /> <property name="builddir" value="build" /> <property name="langdir" value="lang" /> <property name="lib.dir" location="lib" /> <property name="saxonjar" location="${lib.dir}/saxon8.jar" /> <!--  @todo: check JSDoc <property name="jsdoc" value="${basedir}/tools/JSDoc-1.x" /> <property name="doc" value="doc/jsdoc"/> --> <property name="helplocation" value="help" /> <property file="VERSION"/> <!-- PVERSION is for the product version --> <property file="PVERSION"/> <property name="project.name" value="open-xchange-gui" /> <property name="pkg.name" value="open-xchange-gui" /> <property name="deb.optargs" value="" /> <property name="destdir" value="" /> <property name="build.sysclasspath" value="first" />  <target name="build page"> <dependset> <srcfileset dir="html"/> <targetfileset file="${page}.html" /> </dependset> <xslt in="${dir}/${page}.xml" out="${page}.html" style="build.xsl"       classpath="${saxonjar}"> <param name="jstarget" expression="${page}.js" /> <param name="version" expression="${pversion}" /> <xmlcatalog> <dtd publicId="-//W3C//DTD XHTML 1.0 Strict//EN"      location="dtd/xhtml1-strict.dtd" /> </xmlcatalog> </xslt> <replaceregexp file="${page}.html" match="&lt;/(link|br|img|input)&gt;| xmlns(:[a-z]+)?=&quot;[^&quot;]*&quot;" replace="" flags="g" /> </target>  <target name="css"> <xslt in="style.xml" out="${builddir}/border.css" style="css.xsl" /> <concat destfile="ox.css" fixlastline="yes"> <fileset file="${builddir}/border.css" /> <filelist dir="css"> <file name="menu/menu.css" /> <file name="dnd.css" /> <file name="popup.css" /> <file name="tree.css" /> <file name="categories.css" /> <file name="participants.css" /> <file name="sidepanel/sidepanel.css" /> <file name="mail/mail.css" /> <file name="contacts/contacts.css" /> <file name="calendar/calendar.css" /> <file name="calendar/teamww.css" /> <file name="portal/portal.css" /> <file name="global.css" /> <file name="tasks/tasks.css" /> <file name="livegrid.css "/> <file name="infostore/infostore.css" /> </filelist> </concat> </target>  <target name="test resize"> <antcall target="build page"> <param name="page" value="resize" /> <param name="dir" value="tests" /> </antcall> </target>  <target name="html"> <antcall target="build page"> <param name="page" value="index" /> <param name="dir" value="html" /> </antcall> <antcall target="build page"> <param name="page" value="ox" /> <param name="dir" value="html" /> </antcall> <antcall target="build page"> <param name="page" value="newTask" /> <param name="dir" value="html/tasks" /> </antcall> <antcall target="build page"> <param name="page" value="newAppointment" /> <param name="dir" value="html/calendar" /> </antcall> <antcall target="build page"> <param name="page" value="newContact" /> <param name="dir" value="html/contacts" /> </antcall> <antcall target="build page"> <param name="page" value="newContactPicture" /> <param name="dir" value="html/contacts" /> </antcall> <antcall target="build page"> <param name="page" value="newDistributionList" /> <param name="dir" value="html/contacts" /> </antcall> <antcall target="build page"> <param name="page" value="newMail" /> <param name="dir" value="html/mail" /> </antcall> <antcall target="build page"> <param name="page" value="detailMail" /> <param name="dir" value="html/mail" /> </antcall> <antcall target="build page"> <param name="page" value="mailcheck_window" /> <param name="dir" value="html/mail" /> </antcall> <antcall target="build page"> <param name="page" value="newTask" /> <param name="dir" value="html/tasks" /> </antcall> <antcall target="build page"> <param name="page" value="newInfoItemHidden" /> <param name="dir" value="html/infostore" /> </antcall> <antcall target="build page"> <param name="page" value="newInfoItemHidden" /> <param name="dir" value="html/infostore" /> </antcall> <antcall target="build page"> <param name="page" value="newInfoItemMain" /> <param name="dir" value="html/infostore" /> </antcall> <antcall target="build page"> <param name="page" value="newContactHidden" /> <param name="dir" value="html/contacts" /> </antcall> <antcall target="build page"> <param name="page" value="popupContent" /> <param name="dir" value="html" /> </antcall> <replace file="ox.html" token="@helplocation@" value="${helplocation}" summary="yes" /> </target>  <target name="pot">   <xslt basedir="html" destdir="${builddir}" style="i18n/pot.xsl"         extension=".pot" classpath="${saxonjar}">   <param name="root" expression="/html/" /> <xmlcatalog> <dtd publicId="-//W3C//DTD XHTML 1.0 Strict//EN"      location="dtd/xhtml1-strict.dtd" /> </xmlcatalog> <factory>      <attribute name="http://saxon.sf.net/feature/linenumbering" value="true" /> </factory> </xslt>  <concat destfile="${builddir}/js.pot"> <fileset dir="js" includes ="**/*.js" /> <filterchain> <replaceregex pattern="(&quot;([^
