)+msgstr\[.*)*)" replace="\1\\0\3:{\4}" flags="gm" byline="false" /> <replaceregex pattern="^msgstr\[([0-9]+)\] (.*?)\s*$" replace="\1:\2," flags="g" /> <replaceregex pattern="^.*Plural-Forms:\s*nplurals\s*=\s*([0-9]+)\s*;\s*plural\s*=\s*([^;]*);.*&quot;,$"           replace="{nplurals: \1, plural: function(n) { return \2; }, dictionary: {" /> <replaceregex pattern=",\s*$" replace="}}" byline="false" /> </filterchain> </copy> </target>  <!-- @todo: check JSDoc <target name="doc"> <mkdir dir="${doc}"/> <exec executable="${jsdoc}/jsdoc.pl"> <arg value="-r"/> <arg value="- -logo"/> @todo: remove white space!! <arg value="img/oxLogo.png"/> <arg value="-d"/> <arg value="${doc}"/> <arg value="js"/> </exec> </target> -->  <target name="all" depends="css,html,lang" />  <target name="all with clean"> <antcall target="clean" /> <antcall target="all" /> </target>  <target name="clean"> <delete dir="${doc}" /> <delete dir="${builddir}" /> <delete> <fileset dir="${langdir}" includes="**/*" /> </delete> <delete> <fileset dir="." includes="*.html,*.js,ox.css,i18n/ox.pot,*-stamp" /> </delete> <delete dir="debian/${project.name}" /> <delete dir="debian/${pkg.name}" /> <delete file="debian/${project.name}-${version}.tar.bz2" dir="debian/${project.name}-${version}" /> <delete file="debian/files" /> </target>  <target name="deploy" depends="all"> <copy todir="${destdir}/${htdoc}"> <fileset dir="." includes="*.html,*.js,ox.css,lang/**/*,js/**/*,css/**/*,img/**/*,rteditor/**/*" /> </copy> </target>  <target name="install"> <antcall target="deploy"></antcall> </target>  <target name="dist" depends="clean"> <delete dir="debian/${project.name}-${version}" /> <mkdir dir="debian/${project.name}-${version}" />   <copy todir="debian/${project.name}-${version}">     <fileset dir=".">       <exclude name="**debian/**" />       <exclude name="**CVS/**" />     </fileset>   </copy> <tar destfile="debian/${project.name}-${version}.tar.bz2" basedir="debian" includes="${project.name}-${version}/" compression="bzip2" /> </target>  <target name="deb" depends="clean"> <exec executable="dpkg-buildpackage">   <arg line="-rfakeroot -uc -us ${deb.optargs}" /> </exec> <antcall target="clean"></antcall> </target>  </project>
